/* @lc app=leetcode id=1736 lang=kotlin */class Solution {fun maximumTime(time: String): String = IntStream.range(0, time.length).mapToObj { i -> "" + (if (time[i] != '?') time[i] else if (i == 0) if (time[1] <= '3' || time[1] == '?') '2' else '1' else if (i == 1) if ((if (time[0] == '?') if (time[1] <= '3' || time[1] == '?') '2' else '1' else time[0]) == '2') '3' else '9' else if (i == 3) '5' else '9')}.collect(Collectors.joining())}